    peEl.textContent = pe.toFixed(1) + 'x';
    pegEl.textContent = peg.toFixed(2);
    eyEl.textContent = ey.toFixed(2) + '%';
  }

  pEl.addEventListener('input', update);
  epsEl.addEventListener('input', update);
  gEl.addEventListener('input', update);
  update();
})();

peclet-number-microfluidic-molecular-mix.js:
(() => {
  'use strict';
  const vEl = document.getElementById('pec-v'), wEl = document.getElementById('pec-w'), dEl = document.getElementById('pec-d');
  const peResEl = document.getElementById('pec-res-pe'), lmResEl = document.getElementById('pec-res-lmix');

  function update() {
    const vMms = parseFloat(vEl.value), wUm = parseFloat(wEl.value), D = parseFloat(dEl.value);
    if (isNaN(vMms) || isNaN(wUm) || isNaN(D) || vMms <= 0 || wUm <= 0 || D <= 0) return;

    const vMs = vMms * 1e-3;
    const wM = wUm * 1e-6;

    // Peclet number Pe = (v * w) / D
    const Pe = (vMs * wM) / D;

    // Diffusive time t_diff approx = w^2 / (2 * D)
    const t_diff = Math.pow(wM, 2) / (2 * D);

    // Diffusive mixing length L_mix approx = v * t_diff = (v * w^2) / (2 * D) = (w * Pe) / 2
    const L_mix_m = (wM * Pe) / 2;
    const L_mix_mm = L_mix_m * 1000;

    peResEl.textContent = 'Pe = ' + Math.round(Pe).toLocaleString() + ' (Advection / Diffusion Ratio)';

    let mixStrategy = '';
    if (Pe < 1.0) {
      mixStrategy = 'L_mix ≈ ' + L_mix_mm.toFixed(2) + ' mm: Fast Pure Molecular Diffusion';
    } else if (L_mix_mm < 10.0) {
      mixStrategy = 'L_mix ≈ ' + L_mix_mm.toFixed(1) + ' mm: Straight Laminar Co-Flow Channel Sufficient (t_diff = ' + t_diff.toFixed(2) + ' s)';
    } else {
      mixStrategy = 'L_mix ≈ ' + L_mix_mm.toFixed(1) + ' mm (Impractically Long): Staggered Herringbone Chaotic Mixer (SHM) Required';
    }

    lmResEl.textContent = mixStrategy;
  }

  [vEl, wEl, dEl].forEach(el => el.addEventListener('input', update));
  update();
})();

pediatric-clark-rule-young-rule-drug-dos.js:
(() => {
  'use strict';
  const aEl = document.getElementById('ped-adult'), wEl = document.getElementById('ped-wt'), agEl = document.getElementById('ped-age');
  const clkResEl = document.getElementById('ped-res-clark'), yngResEl = document.getElementById('ped-res-young');

  function update() {
    const adultDose = parseFloat(aEl.value), weightKg = parseFloat(wEl.value), ageYears = parseFloat(agEl.value);
    if (isNaN(adultDose) || isNaN(weightKg) || isNaN(ageYears) || adultDose <= 0 || weightKg <= 0 || ageYears <= 0) return;

    // Convert kg to lbs: 1 kg = 2.20462 lbs
    const weightLbs = weightKg * 2.20462;

    // Clark's Rule (Weight-based): Child Dose = ( Weight in lbs / 150 ) * Adult Dose
    const clarkDose = (weightLbs / 150.0) * adultDose;

    // Young's Rule (Age-based for children 1-12 yrs): Child Dose = ( Age / (Age + 12) ) * Adult Dose
    const youngDose = (ageYears / (ageYears + 12.0)) * adultDose;

    clkResEl.textContent = Math.round(clarkDose) + ' mg (Clark's Rule)';
    yngResEl.textContent = 'Young's Rule = ' + Math.round(youngDose) + ' mg | Child Wt: ' + weightKg + ' kg (' + weightLbs.toFixed(1) + ' lbs) @ Adult Dose ' + adultDose + ' mg';
  }

  [aEl, wEl, agEl].forEach(el => el.addEventListener('input', update));
  update();
})();

pediatric-drug-dosage-clark-young-rule-c.js:
(() => {
  'use strict';
  const adEl = document.getElementById('pd-adult'), wEl = document.getElementById('pd-w'), agEl = document.getElementById('pd-age');
  const clResEl = document.getElementById('pd-res-clark'), ygResEl = document.getElementById('pd-res-young');

  function update() {
    const adultDose = parseFloat(adEl.value), W_kg = parseFloat(wEl.value), age = parseFloat(agEl.value);
    if (isNaN(adultDose) || isNaN(W_kg) || isNaN(age) || adultDose <= 0 || W_kg <= 0 || age <= 0) return;

    // Convert kg to lbs:
    const W_lbs = W_kg * 2.20462;

    // Clark's Rule: Child Dose = Adult Dose * (Weight_lbs / 150)
    const clarkDose = adultDose * (W_lbs / 150.0);

    // Young's Rule: Child Dose = Adult Dose * (Age / (Age + 12))
    const youngDose = adultDose * (age / (age + 12.0));

    const fracPct = (clarkDose / adultDose) * 100.0;

    clResEl.textContent = 'Clark's Dose = ' + clarkDose.toFixed(1) + ' mg';
    ygResEl.textContent = 'Young's Dose = ' + youngDose.toFixed(1) + ' mg | Weight = ' + W_lbs.toFixed(1) + ' lbs (' + fracPct.toFixed(1) + '% of ' + adultDose + ' mg adult dose)';
  }

  [adEl, wEl, agEl].forEach(el => el.addEventListener('input', update));
  update();
})();

pelton-wheel-turbine-hydraulic-power-cal.js:
(() => {
  'use strict';
  const hEl = document.getElementById('pel-h'), qEl = document.getElementById('pel-q'), dEl = document.getElementById('pel-d');
  const pResEl = document.getElementById('pel-res-pwr'), jResEl = document.getElementById('pel-res-jet');

  const g = 9.80665;
  const rho_water = 1000;
  const Cv = 0.98;
  const eta = 0.90;

  function update() {
    const H = parseFloat(hEl.value), Q = parseFloat(qEl.value), D = parseFloat(dEl.value);
    if (isNaN(H) || isNaN(Q) || isNaN(D) || H <= 0 || Q <= 0 || D <= 0) return;

    const vJet = Cv * Math.sqrt(2 * g * H);
    const uBucket = 0.46 * vJet;
    const rpm = (uBucket * 60) / (Math.PI * D);

    const pWatts = eta * rho_water * g * Q * H;
    const pKw = pWatts / 1000;
    const pMw = pKw / 1000;

    pResEl.textContent = (pKw >= 1000 ? pMw.toFixed(2) + ' MW' : Math.round(pKw).toLocaleString() + ' kW') + ' (Shaft Power)';
    jResEl.textContent = 'Jet: ' + vJet.toFixed(1) + ' m/s (' + (vJet * 3.6).toFixed(0) + ' km/h) | ' + Math.round(rpm) + ' RPM (Runner D = ' + D + ' m)';
  }

  [hEl, qEl, dEl].forEach(el => el.addEventListener('input', update));
  update();
})();

