percolation-threshold-bethe-lattice-clus.js:
(() => {
  'use strict';
  const latEl = document.getElementById('perc-lat'), pEl = document.getElementById('perc-p');
  const sResEl = document.getElementById('perc-res-span'), stResEl = document.getElementById('perc-res-stat');

  const LATTICES = {
    'square':    { pc: 0.5000, beta_exp: 0.138, name: '2D Square Lattice' },
    'cubic':     { pc: 0.2488, beta_exp: 0.418, name: '3D Cubic Lattice' },
    'honeycomb': { pc: 0.6527, beta_exp: 0.138, name: '2D Honeycomb' },
    'bethe3':    { pc: 0.5000, beta_exp: 1.000, name: 'Bethe Tree z=3' }
  };

  function update() {
    const l = LATTICES[latEl.value];
    const p = parseFloat(pEl.value);

    if (isNaN(p) || p <= 0 || p >= 1.0) return;

    let P_inf = 0.0;
    let status = '';
    let color = '#22543d';

    if (p <= l.pc) {
      P_inf = 0.0;
      status = 'SUBCRITICAL / BLOCKED (p ≤ p_c = ' + l.pc.toFixed(4) + ': Only isolated disconnected micro-clusters exist; zero macroscopic conduction)';
      color = '#c53030';
    } else {
      // Near critical scaling P_inf approx = ( (p - pc) / (1 - pc) )^beta
      const reduced = (p - l.pc) / (1.0 - l.pc);
      P_inf = Math.pow(reduced, l.beta_exp);
      const P_inf_pct = P_inf * 100.0;
      status = 'SUPERCRITICAL PERCOLATION (p > p_c: Continuous giant spanning cluster spans from edge to edge with ' + P_inf_pct.toFixed(1) + '% mass density)';
      color = '#22543d';
    }

    sResEl.textContent = 'P_inf = ' + (P_inf * 100).toFixed(1) + '% (Spanning Strength)';
    sResEl.style.color = color;
    stResEl.textContent = status + ' | ' + l.name + ' (Critical Threshold p_c = ' + l.pc.toFixed(4) + ')';
    stResEl.style.color = color;
  }

  latEl.addEventListener('change', update);
  pEl.addEventListener('input', update);
  update();
})();

permutation-combination-calculator.js:
(() => {
  'use strict';
  const nEl = document.getElementById('ncr-n');
  const rEl = document.getElementById('ncr-r');
  const btn = document.getElementById('primary-action-btn');
  const clearBtn = document.getElementById('clear-action-btn');
  const msgEl = document.getElementById('tool-message');
  const resCard = document.getElementById('ncr-res-card');
  const resComb = document.getElementById('ncr-res-comb');
  const resPerm = document.getElementById('ncr-res-perm');

  function setMsg(t, e) { msgEl.textContent = t; msgEl.className = 'message' + (e ? ' error' : ' success'); }

  function factorial(num) {
    let res = 1n;
    for (let i = 2n; i <= BigInt(num); i++) res *= i;
    return res;
  }

  btn.addEventListener('click', () => {
    const n = parseInt(nEl.value, 10);
    const r = parseInt(rEl.value, 10);

    if (isNaN(n) || isNaN(r) || n < 0 || r < 0 || r > n) {
      setMsg('Please enter valid integers where n >= 0, r >= 0, and r <= n.', true);
      resCard.style.display = 'none';
      return;
    }

    try {
      const factN = factorial(n);
      const factNR = factorial(n - r);
      const factR = factorial(r);

      const nPr = factN / factNR;
      const nCr = nPr / factR;

      resComb.textContent = nCr.toLocaleString();
      resPerm.textContent = nPr.toLocaleString();

      resCard.style.display = 'block';
      setMsg('Permutations and Combinations calculated successfully.');
    } catch (e) {
      setMsg('Values too large for computation.', true);
    }
  });

  clearBtn.addEventListener('click', () => {
    nEl.value = ''; rEl.value = ''; resCard.style.display = 'none';
    msgEl.textContent = 'Ready. Enter parameters above.';
    msgEl.className = 'message';
  });
})();

perspective-projection-fov-frustum-calcu.js:
(() => {
  'use strict';
  const fovEl = document.getElementById('cam-fov'), aspEl = document.getElementById('cam-asp');
  const nEl = document.getElementById('cam-near'), fEl = document.getElementById('cam-far');
  const fcResEl = document.getElementById('cam-res-foc'), hfResEl = document.getElementById('cam-res-hfov');

  function update() {
    const fovVDeg = parseFloat(fovEl.value), aspect = parseFloat(aspEl.value);
    const zNear = parseFloat(nEl.value), zFar = parseFloat(fEl.value);

    if (isNaN(fovVDeg) || isNaN(aspect) || isNaN(zNear) || isNaN(zFar) || fovVDeg <= 0 || fovVDeg >= 180 || zNear <= 0 || zFar <= zNear) return;

    const fovVRad = (fovVDeg * Math.PI) / 180;
    const focalLength = 1 / Math.tan(fovVRad / 2);

    const fovHRad = 2 * Math.atan(Math.tan(fovVRad / 2) * aspect);
    const fovHDeg = (fovHRad * 180) / Math.PI;

    const farHeight = 2 * zFar * Math.tan(fovVRad / 2);
    const farWidth = farHeight * aspect;

    fcResEl.textContent = 'f = ' + focalLength.toFixed(3) + ' (cot(FOV/2))';
    hfResEl.textContent = 'Horizontal FOV: ' + fovHDeg.toFixed(1) + '° (Far Plane: ' + Math.round(farWidth).toLocaleString() + 'm × ' + Math.round(farHeight).toLocaleString() + 'm)';
  }

  [fovEl, nEl, fEl].forEach(el => el.addEventListener('input', update));
  aspEl.addEventListener('change', update);
  update();
})();

pet-scan-positron-range-non-collinearity.js:
(() => {
  'use strict';
  const isoEl = document.getElementById('pet-iso'), crystEl = document.getElementById('pet-cryst'), diaEl = document.getElementById('pet-dia');
  const fResEl = document.getElementById('pet-res-fwhm'), spResEl = document.getElementById('pet-res-split');

  const ISOS = {
    'f18':  { r_range: 0.54, name: 'Fluorine-18 (F-18)' },
    'c11':  { r_range: 0.92, name: 'Carbon-11 (C-11)' },
    'ga68': { r_range: 2.40, name: 'Gallium-68 (Ga-68)' },
    'rb82': { r_range: 5.50, name: 'Rubidium-82 (Rb-82)' }
  };

  function update() {
    const iso = ISOS[isoEl.value];
    const dMm = parseFloat(crystEl.value), ringDiaCm = parseFloat(diaEl.value);

    if (isNaN(dMm) || isNaN(ringDiaCm) || dMm <= 0 || ringDiaCm <= 0) return;

    // 1. Geometric detector resolution R_det = d / 2  [mm]
    const R_det = dMm / 2;

    // 2. Photon non-collinearity blurring R_180 = 0.0022 * D_ring  [mm]
    const D_ring_mm = ringDiaCm * 10;
    const R_180 = 0.0022 * D_ring_mm;

    // 3. Positron kinetic range blurring R_range
    const R_range = iso.r_range;

    // 4. Reconstruction filter blurring R_filter approx 1.0 mm
    const R_filter = 1.0;

    // Total FWHM resolution = sqrt( R_det^2 + R_180^2 + R_range^2 + R_filter^2 )
    const R_total = Math.sqrt(Math.pow(R_det, 2) + Math.pow(R_180, 2) + Math.pow(R_range, 2) + Math.pow(R_filter, 2));

    fResEl.textContent = 'R_FWHM = ' + R_total.toFixed(2) + ' mm (Spatial Resolution)';
    spResEl.textContent = 'Detector: ' + R_det.toFixed(2) + ' mm | 180° Acollinearity: ' + R_180.toFixed(2) + ' mm | Positron Range: ' + R_range.toFixed(2) + ' mm (' + iso.name + ')';
  }

  isoEl.addEventListener('change', update);
  crystEl.addEventListener('input', update);
  diaEl.addEventListener('input', update);
  update();
})();

pet-scan-standardized-uptake-value-suv-t.js:
(() => {
  'use strict';
  const ctEl = document.getElementById('suv-ct'), dsEl = document.getElementById('suv-dose');
  const tEl = document.getElementById('suv-t'), wEl = document.getElementById('suv-w');
  const svResEl = document.getElementById('suv-res-val'), evResEl = document.getElementById('suv-res-eval');

  const half_life_F18 = 109.77; // minutes for Fluorine-18

  function update() {
    const C_tissue_kBq_mL = parseFloat(ctEl.value), Injected_MBq = parseFloat(dsEl.value);
    const time_min = parseFloat(tEl.value), W_kg = parseFloat(wEl.value);

    if (isNaN(C_tissue_kBq_mL) || isNaN(Injected_MBq) || isNaN(time_min) || isNaN(W_kg) || C_tissue_kBq_mL < 0 || Injected_MBq <= 0 || time_min < 0 || W_kg <= 0) return;

    // Decay correction for 18F: Dose_decayed = Dose_inj * exp( - ln(2) * t / t_1/2 )
    const lambda_decay = Math.LN2 / half_life_F18;
    const Decayed_Dose_MBq = Injected_MBq * Math.exp(- lambda_decay * time_min);

    // Injected dose concentration in kBq / g (assuming tissue density 1 g/mL):
    // Dose_conc_kBq_g = (Decayed_Dose_MBq * 1000 kBq/MBq) / (W_kg * 1000 g/kg) = Decayed_Dose_MBq / W_kg
    const Dose_conc = Decayed_Dose_MBq / W_kg;

    // SUV_bw = C_tissue / Dose_conc
    const SUV_bw = C_tissue_kBq_mL / Dose_conc;

    let eval_text = '', color = '#22543d';
    if (SUV_bw > 5.0) {
      eval_text = 'INTENSE HYPERMETABOLISM (Strongly suggestive of active malignancy / high-grade lymphoma/carcinoma)';
      color = '#c53030';
    } else if (SUV_bw >= 2.5) {
      eval_text = 'MODERATE FDG AVIDITY (Malignant lesion or active inflammatory granuloma)';
      color = '#ea580c';
    } else {
      eval_text = 'PHYSIOLOGICAL / BENIGN BACKGROUND (Low metabolic glucose turnover)';
      color = '#22543d';
    }

    svResEl.textContent = 'SUV_bw = ' + SUV_bw.toFixed(2) + ' (' + (SUV_bw >= 2.5 ? 'HYPERMETABOLIC' : 'NORMAL') + ')';
    svResEl.style.color = color;
    evResEl.textContent = eval_text + ' [Decayed Dose = ' + Decayed_Dose_MBq.toFixed(1) + ' MBq @ ' + time_min + ' min post-injection, W = ' + W_kg + ' kg]';
  }

  [ctEl, dsEl, tEl, wEl].forEach(el => el.addEventListener('input', update));
  update();
})();

petroff-bearing-friction-power-loss-calc.js:
(() => {
  'use strict';
  const rEl = document.getElementById('pet-r'), lEl = document.getElementById('pet-l');
  const cEl = document.getElementById('pet-c'), muEl = document.getElementById('pet-mu'), rpmEl = document.getElementById('pet-rpm');
  const pResEl = document.getElementById('pet-res-pwr'), tResEl = document.getElementById('pet-res-trq');

  function update() {
    const rMm = parseFloat(rEl.value), lMm = parseFloat(lEl.value);
    const cUm = parseFloat(cEl.value), muCp = parseFloat(muEl.value), RPM = parseFloat(rpmEl.value);

    if (isNaN(rMm) || isNaN(lMm) || isNaN(cUm) || isNaN(muCp) || isNaN(RPM) || rMm <= 0 || lMm <= 0 || cUm <= 0 || muCp <= 0 || RPM <= 0) return;

    const r_m = rMm * 1e-3;
    const l_m = lMm * 1e-3;
    const c_m = cUm * 1e-6;
    const mu_pa_s = muCp * 1e-3;

    // Angular velocity omega = 2 * pi * RPM / 60  [rad / s]
    const omega = (2.0 * Math.PI * RPM) / 60.0;

    // Surface tangential velocity U = omega * r
    const U = omega * r_m;
    // Shear rate gamma_dot = U / c
    const gamma_dot = U / c_m;

    // Petroff's law friction torque: T = 2 * pi * mu * omega * r^3 * L / c  [N * m]
    const Torque_Nm = (2.0 * Math.PI * mu_pa_s * omega * Math.pow(r_m, 3) * l_m) / c_m;

    // Power loss P = Torque * omega  [Watts]
    const Power_watts = Torque_Nm * omega;
    const Power_hp = Power_watts / 745.7;

    pResEl.textContent = 'P_loss = ' + Power_watts.toFixed(1) + ' Watts (' + Power_hp.toFixed(2) + ' HP Heat Dissipation)';
    tResEl.textContent = 'Friction Torque T = ' + Torque_Nm.toFixed(3) + ' N·m | Shear Rate γ̇ = ' + gamma_dot.toExponential(2) + ' s⁻¹ (Surface Speed = ' + U.toFixed(2) + ' m/s)';
  }

  [rEl, lEl, cEl, muEl, rpmEl].forEach(el => el.addEventListener('input', update));
  update();
})();

pfr-plug-flow-reactor-space-time-calcula.js:
(() => {
  'use strict';
  const v0El = document.getElementById('pfr-v0'), xEl = document.getElementById('pfr-x'), kEl = document.getElementById('pfr-k');
  const vResEl = document.getElementById('pfr-res-vol'), tauResEl = document.getElementById('pfr-res-tau');

  function update() {
    const v0 = parseFloat(v0El.value), xPct = parseFloat(xEl.value), k = parseFloat(kEl.value);
    if (isNaN(v0) || isNaN(xPct) || isNaN(k) || v0 <= 0 || xPct <= 0 || xPct >= 100 || k <= 0) return;

    const X = xPct / 100;
    // For 1st order PFR: tau = -ln(1 - X) / k  [min]
    const tau = -Math.log(1 - X) / k;
    // Volume V = v0 * tau  [Liters]
    const V_liters = v0 * tau;
    const V_m3 = V_liters / 1000;

    vResEl.textContent = V_liters.toFixed(1) + ' Liters (' + V_m3.toFixed(3) + ' m³)';
    tauResEl.textContent = 'τ = ' + tau.toFixed(2) + ' Minutes (' + Math.round(tau * 60) + ' seconds Residence Time)';
  }

  [v0El, xEl, kEl].forEach(el => el.addEventListener('input', update));
  update();
})();

pfr-plug-flow-reactor-volume-calculator.js:
(() => {
  'use strict';
  const fa0El = document.getElementById('pfr-fa0'), ca0El = document.getElementById('pfr-ca0');
  const xEl = document.getElementById('pfr-x'), kEl = document.getElementById('pfr-k');
  const vResEl = document.getElementById('pfr-res-vol'), cResEl = document.getElementById('pfr-res-cmp');

  function update() {
    const Fa0 = parseFloat(fa0El.value), Ca0 = parseFloat(ca0El.value);
    const X = parseFloat(xEl.value), k = parseFloat(kEl.value);

    if (isNaN(Fa0) || isNaN(Ca0) || isNaN(X) || isNaN(k) || Fa0 <= 0 || Ca0 <= 0 || X <= 0 || X >= 1.0 || k <= 0) return;

    // PFR 1st-order: V_pfr = (Fa0 / (k * Ca0)) * ln( 1 / (1 - X) )
    const V_pfr = (Fa0 / (k * Ca0)) * Math.log(1 / (1 - X));

    // CSTR for same conversion: V_cstr = (Fa0 * X) / (k * Ca0 * (1 - X))
    const V_cstr = (Fa0 * X) / (k * Ca0 * (1 - X));
    const savingsPct = ((V_cstr - V_pfr) / V_cstr) * 100;

    const Q = Fa0 / Ca0;
    const tau_pfr = V_pfr / Q;

    vResEl.textContent = V_pfr.toFixed(1) + ' Liters (PFR Space Time τ = ' + tau_pfr.toFixed(1) + ' s)';
    cResEl.textContent = savingsPct.toFixed(1) + '% Volume Savings vs CSTR (PFR: ' + V_pfr.toFixed(1) + ' L vs CSTR: ' + V_cstr.toFixed(1) + ' L @ ' + (X*100) + '% Conv)';
  }

  [fa0El, ca0El, xEl, kEl].forEach(el => el.addEventListener('input', update));
  update();
})();

ph-calculator.js:
﻿(function() {
  'use strict';
  var slug = 'ph-calculator';
  var modeEl = document.getElementById(slug + '-mode');
  var inputEl = document.getElementById(slug + '-input');
  var outputEl = document.getElementById(slug + '-output');
  var msgEl = document.getElementById(slug + '-message');
  var btn = document.getElementById('primary-action-btn');
  var copyBtn = document.getElementById('copy-output');
  var clearBtn = document.getElementById('clear-text');
  function setMsg(t, e){ msgEl.textContent=t; msgEl.classList.toggle('is-error', !!e); }
  btn.addEventListener('click', function() {
    var val = parseFloat(inputEl.value);
    if (isNaN(val)) { setMsg('Please enter a valid number.', true); outputEl.value=''; copyBtn.disabled=true; return; }
    var mode = modeEl.value;
    var out = '';
    if (mode === 'ph') {
      if (val <= 0) { setMsg('H+ concentration must be positive.', true); return; }
      var ph = -Math.log10(val);
      var poh = 14 - ph;
      out = 'Formula: pH = -log₁₀[H⁺]\n\n';
      out += '[H⁺] = ' + val + ' mol/L\n';
      out += 'pH = ' + ph.toFixed(4) + '\n';
      out += 'pOH = 14 - pH = ' + poh.toFixed(4) + '\n\n';
      out += 'Nature: ' + (ph < 7 ? 'Acidic' : ph > 7 ? 'Basic/Alkaline' : 'Neutral');
    } else if (mode === 'h') {
      if (val < 0 || val > 14) { setMsg('pH must be between 0 and 14.', true); return; }
      var h = Math.pow(10, -val);
      var poh2 = 14 - val;
      out = 'Formula: [H⁺] = 10^(-pH)\n\n';
      out += 'pH = ' + val + '\n';
      out += '[H⁺] = ' + h.toExponential(4) + ' mol/L\n';
      out += 'pOH = ' + poh2.toFixed(4) + '\n\n';
      out += 'Nature: ' + (val < 7 ? 'Acidic' : val > 7 ? 'Basic/Alkaline' : 'Neutral');
    } else {
      if (val <= 0) { setMsg('OH- concentration must be positive.', true); return; }
      var poh3 = -Math.log10(val);
      var ph3 = 14 - poh3;
      out = 'Formula: pOH = -log₁₀[OH⁻]\n\n';
      out += '[OH⁻] = ' + val + ' mol/L\n';
      out += 'pOH = ' + poh3.toFixed(4) + '\n';
      out += 'pH = 14 - pOH = ' + ph3.toFixed(4) + '\n\n';
      out += 'Nature: ' + (ph3 < 7 ? 'Acidic' : ph3 > 7 ? 'Basic/Alkaline' : 'Neutral');
    }
    outputEl.value = out;
    copyBtn.disabled = false;
    setMsg('Calculation complete.');
  });
  copyBtn.addEventListener('click', function() { if (window.NikTool && typeof window.NikTool.copy === 'function') { window.NikTool.copy(outputEl.value, copyBtn); } else if (navigator.clipboard) { navigator.clipboard.writeText(outputEl.value); } setMsg('Result copied.'); });
  clearBtn.addEventListener('click', function() { inputEl.value=''; outputEl.value=''; copyBtn.disabled=true; setMsg('Cleared.'); });
})();

ph-poh-hydrogen-ion-calculator.js:
(() => {
  'use strict';
  const typeEl = document.getElementById('ph-type'), valEl = document.getElementById('ph-val');
  const phEl = document.getElementById('ph-res-ph'), pohEl = document.getElementById('ph-res-poh');
  const hEl = document.getElementById('ph-res-h'), ohEl = document.getElementById('ph-res-oh'), classEl = document.getElementById('ph-res-class');

  function update() {
    const type = typeEl.value;
    const raw = parseFloat(valEl.value);
    if (isNaN(raw) || raw <= 0) return;

    let pH = 7.0;
    if (type === 'ph') pH = raw;
    else if (type === 'poh') pH = 14.0 - raw;
    else if (type === 'h') pH = -Math.log10(raw);
    else if (type === 'oh') pH = 14.0 - (-Math.log10(raw));

    pH = Math.max(0, Math.min(14, pH));
    const pOH = 14.0 - pH;
    const hConc = Math.pow(10, -pH);
    const ohConc = Math.pow(10, -pOH);

    phEl.textContent = pH.toFixed(2);
    pohEl.textContent = pOH.toFixed(2);
    hEl.textContent = hConc.toExponential(2);
    ohEl.textContent = ohConc.toExponential(2);

    if (Math.abs(pH - 7.0) < 0.05) classEl.textContent = 'Neutral (Pure Water)';
    else if (pH < 3) classEl.textContent = 'Strongly Acidic';
    else if (pH < 7) classEl.textContent = 'Weakly Acidic';
    else if (pH < 11) classEl.textContent = 'Weakly Alkaline / Basic';
    else classEl.textContent = 'Strongly Alkaline / Basic';
  }

  typeEl.addEventListener('change', update);
  valEl.addEventListener('input', update);
  update();
})();

ph-poh-hydrogen-ion-concentration-conver.js:
(() => {
  'use strict';
  const phEl = document.getElementById('ph-in'), hEl = document.getElementById('ph-hplus');
  const pohResEl = document.getElementById('ph-res-poh'), scResEl = document.getElementById('ph-res-scale');

  function fromPh() {
    const pH = parseFloat(phEl.value);
    if (isNaN(pH) || pH < 0 || pH > 14) return;

    // [H+] = 10^(-pH)
    const H_conc = Math.pow(10, -pH);
    hEl.value = H_conc.toExponential(2);

    // pOH = 14 - pH
    const pOH = 14.0 - pH;
    const OH_conc = Math.pow(10, -pOH);

    let nature = '';
    let color = '#22543d';

    if (pH < 3.0) { nature = 'STRONGLY ACIDIC (pH < 3.0: Stomach Acid / Lemon Juice)'; color = '#c53030'; }
    else if (pH < 6.5) { nature = 'WEAKLY ACIDIC (pH 3.0 - 6.5: Coffee / Rainwater / Milk)'; color = '#ea580c'; }
