  const bResEl = document.getElementById('pl-res-b'), qResEl = document.getElementById('pl-res-quant');

  const h = 6.62607015e-34, c = 299792458, k_B = 1.380649e-23;

  function update() {
    const lambda_nm = parseFloat(lEl.value), T = parseFloat(tEl.value);
