      color = '#2563eb';
    }

    tqResEl.textContent = 'Equilibrium T_eq = ' + T_eq.toFixed(1) + ' K (' + (T_eq_C >= 0 ? '+' : '') + T_eq_C.toFixed(1) + ' °C)';
    tqResEl.style.color = color;
