(() => {
  'use strict';
  const dpEl = document.getElementById('ps-dp'), rEl = document.getElementById('ps-r');
  const lEl = document.getElementById('ps-l'), etEl = document.getElementById('ps-eta');
  const qResEl = document.getElementById('ps-res-q'), snResEl = document.getElementById('ps-res-sens');

  function update() {
    const dP_mmHg = parseFloat(dpEl.value), r_mm = parseFloat(rEl.value);
    const L_cm = parseFloat(lEl.value), eta_cP = parseFloat(etEl.value);

    if (isNaN(dP_mmHg) || isNaN(r_mm) || isNaN(L_cm) || isNaN(eta_cP) || dP_mmHg <= 0 || r_mm <= 0 || L_cm <= 0 || eta_cP <= 0) return;

    // Convert to SI units:
    // 1 mmHg = 133.322 Pa
    const dP_Pa = dP_mmHg * 133.322;
    // r in meters: 1 mm = 1e-3 m
    const r_m = r_mm * 1e-3;
    // L in meters: 1 cm = 1e-2 m
    const L_m = L_cm * 1e-2;
    // Viscosity in Pa*s: 1 cP = 1e-3 Pa*s
    const eta_Pas = eta_cP * 1e-3;

    // Hagen-Poiseuille flow Q in m^3 / s:
    // Q = ( pi * r^4 * dP ) / ( 8 * eta * L )
    const Q_m3_s = (Math.PI * Math.pow(r_m, 4) * dP_Pa) / (8.0 * eta_Pas * L_m);

    // Convert Q to mL / min: 1 m^3/s = 1e6 mL/s = 6e7 mL/min
    const Q_mL_min = Q_m3_s * 6e7;

    // Vascular resistance in mmHg * min / mL:
    const R_vasc = dP_mmHg / Q_mL_min;

    qResEl.textContent = 'Blood Flow Q = ' + Math.round(Q_mL_min).toLocaleString() + ' mL / min';
    snResEl.textContent = 'Vascular Resistance R = ' + R_vasc.toExponential(2) + ' mmHg·min/mL | Halving radius (r/2) increases resistance by 16× (r⁴ = ' + Math.pow(r_mm, 4).toFixed(2) + ' mm⁴)';
  }

  [dpEl, rEl, lEl, etEl].forEach(el => el.addEventListener('input', update));
  update();
})();

poisson-distribution-probability-calcula.js:
(() => {
  'use strict';
  const lamEl = document.getElementById('ps-lam'), kEl = document.getElementById('ps-k');
  const exResEl = document.getElementById('ps-res-exact'), cmResEl = document.getElementById('ps-res-cumul');

  function fact(n) {
    let res = 1;
    for (let i = 2; i <= n; i++) res *= i;
    return res;
  }

  function poissonP(lambda, k) {
    if (k < 0) return 0;
    return (Math.pow(lambda, k) * Math.exp(-lambda)) / fact(k);
  }

  function update() {
    const lam = parseFloat(lamEl.value), k = parseInt(kEl.value, 10);
    if (isNaN(lam) || isNaN(k) || lam <= 0 || k < 0 || k > 100) return;

    const pExact = poissonP(lam, k);
    let pCumul = 0;
    for (let i = 0; i <= k; i++) pCumul += poissonP(lam, i);

    exResEl.textContent = pExact.toFixed(4) + ' (' + (pExact * 100).toFixed(2) + '%)';
    cmResEl.textContent = 'P(X ≤ ' + k + ') = ' + (pCumul * 100).toFixed(2) + '% (Variance σ² = ' + lam.toFixed(1) + ')';
  }

  lamEl.addEventListener('input', update);
  kEl.addEventListener('input', update);
  update();
})();

poisson-process-inter-arrival-time-queue.js:
(() => {
  'use strict';
  const lamEl = document.getElementById('q-lam'), muEl = document.getElementById('q-mu');
  const rResEl = document.getElementById('q-res-rho'), wqResEl = document.getElementById('q-res-wq');

  function update() {
    const lambda = parseFloat(lamEl.value), mu = parseFloat(muEl.value);
    if (isNaN(lambda) || isNaN(mu) || lambda <= 0 || mu <= 0) return;

    // Traffic intensity utilization rho = lambda / mu
    const rho = lambda / mu;

    if (rho >= 1.0) {
      rResEl.textContent = 'UNSTABLE QUEUE (ρ = ' + (rho * 100).toFixed(1) + '% ≥ 100%)';
      rResEl.style.color = '#c53030';
      wqResEl.textContent = 'Arrival rate exceeds service capacity (λ ≥ μ): Queue grows infinitely without bound!';
      wqResEl.style.color = '#c53030';
      return;
    }

    // Average number in system L = rho / (1 - rho)
    const L = rho / (1.0 - rho);
    // Average number in queue L_q = rho^2 / (1 - rho) = L - rho
    const L_q = Math.pow(rho, 2) / (1.0 - rho);

    // Average time in system W = 1 / (mu - lambda)  [hours -> minutes]
    const W_hours = 1.0 / (mu - lambda);
    const W_min = W_hours * 60.0;

    // Average time in queue W_q = rho / (mu - lambda)  [hours -> minutes]
    const W_q_hours = rho / (mu - lambda);
    const W_q_min = W_q_hours * 60.0;

    let color = rho > 0.85 ? '#d97706' : '#22543d';

    rResEl.textContent = 'Utilization ρ = ' + (rho * 100).toFixed(1) + '%';
    rResEl.style.color = color;
    wqResEl.textContent = 'Average Wait in Line W_q = ' + W_q_min.toFixed(1) + ' min (Line Length L_q = ' + L_q.toFixed(2) + ' | Total System Time W = ' + W_min.toFixed(1) + ' min)';
    wqResEl.style.color = color;
  }

  lamEl.addEventListener('input', update);
  muEl.addEventListener('input', update);
  update();
})();

