polynomial-calculator.js:
﻿(function() {
  'use strict';
  var slug = 'polynomial-calculator';
  var coefEl = document.getElementById(slug + '-input');
  var xEl = document.getElementById(slug + '-x');
  var outputEl = document.getElementById(slug + '-output');
  var msgEl = document.getElementById(slug + '-message');
  var btn = document.getElementById('primary-action-btn');
  var copyBtn = document.getElementById('copy-output');
  var clearBtn = document.getElementById('clear-text');
  function setMsg(t, e){ msgEl.textContent=t; msgEl.classList.toggle('is-error', !!e); }
  btn.addEventListener('click', function() {
    var coefs = coefEl.value.split(/[\s,]+/).map(function(s){return s.trim();}).filter(Boolean).map(Number);
    if (!coefs.length || coefs.some(isNaN)) { setMsg('Please enter valid coefficients.', true); outputEl.value=''; copyBtn.disabled=true; return; }
    var x = parseFloat(xEl.value);
    if (isNaN(x)) { setMsg('Please enter a valid value for x.', true); return; }
    var degree = coefs.length - 1;
    var terms = coefs.map(function(c, i) {
      var power = degree - i;
      if (c === 0) return null;
      var termStr = (c === 1 && power !== 0 ? '' : (c === -1 && power !== 0 ? '-' : c));
      if (power === 0) return String(c);
      if (power === 1) return termStr + 'x';
      return termStr + 'x^' + power;
    }).filter(Boolean);
    var result = 0;
    for (var i = 0; i < coefs.length; i++) {
      result += coefs[i] * Math.pow(x, degree - i);
    }
    var out = 'Polynomial: ' + (terms.join(' + ').replace(/\+ -/g, '- ') || '0') + '\n';
    out += 'Degree: ' + degree + '\n';
    out += 'Leading Coefficient: ' + coefs[0] + '\n\n';
    out += 'At x = ' + x + ':\n';
    out += 'P(' + x + ') = ' + result.toFixed(4);
    outputEl.value = out;
    copyBtn.disabled = false;
    setMsg('Polynomial evaluated successfully.');
  });
  copyBtn.addEventListener('click', function() {
    if (window.NikTool && typeof window.NikTool.copy === 'function') { window.NikTool.copy(outputEl.value, copyBtn); }
    else if (navigator.clipboard) { navigator.clipboard.writeText(outputEl.value); }
    setMsg('Result copied to clipboard.');
  });
  clearBtn.addEventListener('click', function() {
    coefEl.value=''; xEl.value=''; outputEl.value=''; copyBtn.disabled=true;
    setMsg('Cleared. Enter coefficients and x above.');
  });
})();

porkchop-plot-hyperbolic-excess-velocity.js:
(() => {
  'use strict';
  const viEl = document.getElementById('c3-vinf'), altEl = document.getElementById('c3-alt');
  const c3ResEl = document.getElementById('c3-res-c3'), tmResEl = document.getElementById('c3-res-tmi');

  const mu_E = 398600.4418; // km^3 / s^2
  const R_E = 6378.137; // km

  function update() {
    const v_inf = parseFloat(viEl.value), h_km = parseFloat(altEl.value);
    if (isNaN(v_inf) || isNaN(h_km) || v_inf < 0 || h_km < 0) return;

    // Characteristic energy C3: C3 = v_inf^2  [km^2 / s^2]
    const C3 = Math.pow(v_inf, 2);

    const r_park = R_E + h_km;

    // Circular parking velocity: v_park = sqrt( mu / r )
    const v_park = Math.sqrt(mu_E / r_park);

    // Escape velocity from parking orbit: v_esc = sqrt( 2 * mu / r )
    const v_esc = Math.sqrt(2.0 * mu_E / r_park);

    // Hyperbolic injection velocity at periapsis: v_inj = sqrt( v_esc^2 + v_inf^2 ) = sqrt( 2*mu/r + C3 )
    const v_inj = Math.sqrt(Math.pow(v_esc, 2) + C3);

    // Injection delta-v: Delta_v_inj = v_inj - v_park
    const delta_v_inj = v_inj - v_park;

    c3ResEl.textContent = 'Launch Energy C3 = ' + C3.toFixed(2) + ' km² / s²';
    tmResEl.textContent = 'Injection Burn Δv = ' + delta_v_inj.toFixed(3) + ' km/s (v_inj = ' + v_inj.toFixed(3) + ' km/s vs v_park = ' + v_park.toFixed(3) + ' km/s @ ' + h_km + ' km LEO)';
  }

  viEl.addEventListener('input', update);
  altEl.addEventListener('input', update);
  update();
})();

