(() => {
  'use strict';
  const t1El = document.getElementById('bt-t1'), t2El = document.getElementById('bt-t2');
  const a10El = document.getElementById('bt-a10'), tmEl = document.getElementById('bt-time');
  const a2ResEl = document.getElementById('bt-res-a2'), eqResEl = document.getElementById('bt-res-eq');

  function update() {
    const T1_hr = parseFloat(t1El.value), T2_hr = parseFloat(t2El.value);
    const A10_MBq = parseFloat(a10El.value), t_hr = parseFloat(tmEl.value);

    if (isNaN(T1_hr) || isNaN(T2_hr) || isNaN(A10_MBq) || isNaN(t_hr) || T1_hr <= 0 || T2_hr <= 0 || A10_MBq <= 0 || t_hr < 0 || T1_hr === T2_hr) return;

    const lambda1 = Math.LN2 / T1_hr;
    const lambda2 = Math.LN2 / T2_hr;

    const A1_MBq = A10_MBq * Math.exp(-lambda1 * t_hr);
    const factor = lambda2 / (lambda2 - lambda1);
    const A2_MBq = factor * A10_MBq * (Math.exp(-lambda1 * t_hr) - Math.exp(-lambda2 * t_hr));
    const t_max_hr = Math.log(lambda2 / lambda1) / (lambda2 - lambda1);

    let mode = '';
    if (T1_hr > 100.0 * T2_hr) {
      mode = 'SECULAR EQUILIBRIUM (T₁ >> T₂: A₂ approaches A₁ at long times)';
    } else if (T1_hr > T2_hr) {
      const eq_ratio = lambda2 / (lambda2 - lambda1);
      mode = 'TRANSIENT EQUILIBRIUM (T₁ > T₂: Ingrowth peak @ ' + t_max_hr.toFixed(1) + ' hr, asymptotic A₂/A₁ = ' + eq_ratio.toFixed(2) + ')';
    } else {
      mode = 'NO EQUILIBRIUM (T₁ < T₂: Daughter decays slower than parent)';
    }

    a2ResEl.textContent = 'Daughter Activity A₂ = ' + A2_MBq.toFixed(1) + ' MBq';
    eqResEl.textContent = 'Parent A₁ = ' + A1_MBq.toFixed(1) + ' MBq | ' + mode + ' [t_peak = ' + t_max_hr.toFixed(1) + ' hr]';
  }

  [t1El, t2El, a10El, tmEl].forEach(el => el.addEventListener('input', update));
  update();
})();

radioactive-decay-chain-bateman-equation.js:
(() => {
  'use strict';
  const th1El = document.getElementById('bat-th1'), th2El = document.getElementById('bat-th2');
  const a0El = document.getElementById('bat-a0'), tmEl = document.getElementById('bat-time');
  const adResEl = document.getElementById('bat-res-ad'), pkResEl = document.getElementById('bat-res-peak');

  function update() {
    const Th1 = parseFloat(th1El.value), Th2 = parseFloat(th2El.value);
    const A0 = parseFloat(a0El.value), t = parseFloat(tmEl.value);

    if (isNaN(Th1) || isNaN(Th2) || isNaN(A0) || isNaN(t) || Th1 <= 0 || Th2 <= 0 || A0 <= 0 || t < 0) return;

    const lambda1 = Math.LN2 / Th1;
    const lambda2 = Math.LN2 / Th2;

    // Parent activity A1(t) = A0 * exp(-lambda1 * t)
    const A1_t = A0 * Math.exp(-lambda1 * t);

    // Bateman equation for daughter activity A2(t):
    // A2(t) = A0 * ( lambda2 / (lambda2 - lambda1) ) * ( exp(-lambda1*t) - exp(-lambda2*t) )
    const A2_t = A0 * (lambda2 / (lambda2 - lambda1)) * (Math.exp(-lambda1 * t) - Math.exp(-lambda2 * t));

    // Time of maximum daughter activity: t_max = ln(lambda2 / lambda1) / (lambda2 - lambda1)
    const t_max = Math.log(lambda2 / lambda1) / (lambda2 - lambda1);
    const A2_max = A0 * (lambda2 / (lambda2 - lambda1)) * (Math.exp(-lambda1 * t_max) - Math.exp(-lambda2 * t_max));

    adResEl.textContent = A2_t.toFixed(1) + ' GBq Daughter Activity (Parent: ' + A1_t.toFixed(1) + ' GBq)';
    pkResEl.textContent = 'Peak: ' + A2_max.toFixed(1) + ' GBq @ t_max = ' + t_max.toFixed(1) + ' h (' + (Th1 > Th2 ? 'Transient Equilibrium A₂/A₁ = ' + (lambda2/(lambda2-lambda1)).toFixed(2) : 'No Equilibrium') + ')';
  }

  [th1El, th2El, a0El, tmEl].forEach(el => el.addEventListener('input', update));
  update();
})();

