    // Thermal efficiency: eta = w_net / q_in
    const eta_pct = (w_net / q_in) * 100.0;

    // Net Heat Rate (kJ / kWh) = 3600 / (eta / 100)
    const heatRate_kJ_kWh = 3600.0 / (eta_pct / 100.0);

    efResEl.textContent = 'Thermal Efficiency η_th = ' + eta_pct.toFixed(2) + '%';
