(() => {
  'use strict';
  const n1El = document.getElementById('tir-n1'), n2El = document.getElementById('tir-n2');
  const crResEl = document.getElementById('tir-res-crit'), spResEl = document.getElementById('tir-res-spd');

  const c_light = 2.99792e8; // m/s

  function update() {
    const n1 = parseFloat(n1El.value), n2 = parseFloat(n2El.value);
    if (isNaN(n1) || isNaN(n2) || n1 <= 0 || n2 <= 0 || n1 <= n2) {
      crResEl.textContent = 'No Total Internal Reflection (n₁ must be > n₂)';
      crResEl.style.color = '#c53030';
      spResEl.textContent = 'TIR only occurs when light travels from a denser to rarer medium.';
      return;
    }

    // Critical angle sin(theta_c) = n2 / n1
    const sin_theta = n2 / n1;
    const theta_c_rad = Math.asin(sin_theta);
    const theta_c_deg = (theta_c_rad * 180.0) / Math.PI;

    // Speed in medium 1: v = c / n1
    const v_med = c_light / n1;

    crResEl.textContent = 'θ_c = ' + theta_c_deg.toFixed(2) + '° (Critical Angle)';
    crResEl.style.color = '#22543d';
    spResEl.textContent = 'Speed in Core = ' + (v_med / 1e8).toFixed(2) + ' × 10⁸ m/s | 100% Light Trapped for θ_inc > ' + theta_c_deg.toFixed(2) + '°';
  }

  n1El.addEventListener('input', update);
  n2El.addEventListener('input', update);
  update();
})();

refrigerant-pressure-temperature-pt-char.js:
(() => {
  'use strict';
  const rEl = document.getElementById('pt-ref'), tEl = document.getElementById('pt-temp');
  const pResEl = document.getElementById('pt-res-psig'), aResEl = document.getElementById('pt-res-psia');

  // Antoine saturation vapor pressure fit: ln(P_psia) = A - B / (T_F + C)
  const COEFFS = {
    'R410A': { A: 10.35, B: 3450, C: 430 },
    'R134a': { A: 9.85, B: 3520, C: 410 },
    'R32':   { A: 10.42, B: 3500, C: 435 },
    'R404A': { A: 10.20, B: 3380, C: 425 }
  };

  function update() {
    const ref = rEl.value, tF = parseFloat(tEl.value);
    if (isNaN(tF)) return;

    const c = COEFFS[ref];
    const lnP = c.A - (c.B / (tF + c.C));
    const psia = Math.exp(lnP);
    const psig = psia - 14.696;
    const barGauge = psig * 0.0689476;

    pResEl.textContent = (psig >= 0 ? psig.toFixed(1) + ' psig' : (psig * 2.036).toFixed(1) + ' in.Hg vacuum') + ' (' + (barGauge).toFixed(2) + ' bar)';
    aResEl.textContent = psia.toFixed(1) + ' psia (' + (psia * 6.89476).toFixed(1) + ' kPa abs)';
  }

  rEl.addEventListener('change', update);
  tEl.addEventListener('input', update);
  update();
})();

refrigeration-carnot-cop-efficiency-calc.js:
(() => {
  'use strict';
  const tcEl = document.getElementById('ref-tc'), thEl = document.getElementById('ref-th');
  const qcEl = document.getElementById('ref-qc'), efEl = document.getElementById('ref-eff');
  const cResEl = document.getElementById('ref-res-cop'), pResEl = document.getElementById('ref-res-pwr');

  function update() {
    const Tc_c = parseFloat(tcEl.value), Th_c = parseFloat(thEl.value);
    const Qc_kw = parseFloat(qcEl.value), eff = parseFloat(efEl.value);

    if (isNaN(Tc_c) || isNaN(Th_c) || isNaN(Qc_kw) || isNaN(eff) || Th_c <= Tc_c || Qc_kw <= 0 || eff <= 0 || eff > 1.0) return;

    const Tc_k = Tc_c + 273.15;
    const Th_k = Th_c + 273.15;

    const copCarnot = Tc_k / (Th_k - Tc_k);
    const copReal = copCarnot * eff;

    const W_kw = Qc_kw / copReal;
    const W_hp = W_kw * 1.34102;
    const eer = copReal * 3.412142;

    cResEl.textContent = 'Real COP = ' + copReal.toFixed(2) + ' (Carnot Max: ' + copCarnot.toFixed(2) + ')';
    pResEl.textContent = 'Input Power: ' + W_kw.toFixed(2) + ' kW (' + W_hp.toFixed(2) + ' HP) | EER: ' + eer.toFixed(1) + ' (Lift: ' + (Th_c - Tc_c).toFixed(1) + '°C)';
  }

  [tcEl, thEl, qcEl, efEl].forEach(el => el.addEventListener('input', update));
  update();
})();

