reid-vapor-pressure-rvp-crude-oil-blendi.js:
(() => {
  'use strict';
  const bVEl = document.getElementById('rvp-but-vol'), aVEl = document.getElementById('rvp-alk-vol');
  const rVEl = document.getElementById('rvp-ref-vol'), fVEl = document.getElementById('rvp-fcc-vol');
  const bResEl = document.getElementById('rvp-res-blend'), epaResEl = document.getElementById('rvp-res-epa');

  // Component pure RVPs in psi:
  const RVP_but = 52.0;  // n-Butane
  const RVP_alk = 5.0;   // Alkylate
  const RVP_ref = 3.5;   // Reformate
  const RVP_fcc = 11.5;  // FCC Naphtha

  function update() {
    const vBut = parseFloat(bVEl.value), vAlk = parseFloat(aVEl.value);
    const vRef = parseFloat(rVEl.value), vFcc = parseFloat(fVEl.value);

    if (isNaN(vBut) || isNaN(vAlk) || isNaN(vRef) || isNaN(vFcc)) return;

    const totalVol = vBut + vAlk + vRef + vFcc;
    if (totalVol === 0) return;

    // Chevron 1.25 power blending index method:
    // Blend Index BI = sum( (v_i / totalVol) * (RVP_i)^1.25 )
    // RVP_blend = (BI)^(1 / 1.25)
    const BI = ((vBut / totalVol) * Math.pow(RVP_but, 1.25)) +
               ((vAlk / totalVol) * Math.pow(RVP_alk, 1.25)) +
               ((vRef / totalVol) * Math.pow(RVP_ref, 1.25)) +
               ((vFcc / totalVol) * Math.pow(RVP_fcc, 1.25));

    const RVP_blend_psi = Math.pow(BI, 1.0 / 1.25);
    const RVP_blend_kpa = RVP_blend_psi * 6.89476;

    let epaStatus = '';
    let color = '#22543d';

    if (RVP_blend_psi <= 7.80) {
      epaStatus = 'EPA STRICT REFORMULATED (RFG) SUMMER COMPLIANT (RVP ≤ 7.8 psi: High Ozone Non-Attainment)';
      color = '#22543d';
    } else if (RVP_blend_psi <= 9.00) {
      epaStatus = 'EPA CONVENTIONAL SUMMER COMPLIANT (RVP ≤ 9.0 psi Federal Standard)';
      color = '#22543d';
    } else if (RVP_blend_psi <= 13.5) {
      epaStatus = 'WINTER GASOLINE SPECIFICATION (RVP 11.5 - 13.5 psi: Easy Cold Weather Engine Starting)';
      color = '#2563eb';
    } else {
      epaStatus = 'VAPOR LOCK RISK: RVP exceeds 13.5 psi - Risk of hot fuel pump cavitation vapor lock!';
      color = '#c53030';
    }

    bResEl.textContent = 'RVP = ' + RVP_blend_psi.toFixed(2) + ' psi (' + RVP_blend_kpa.toFixed(1) + ' kPa)';
    epaResEl.textContent = epaStatus + ' (Total Volume: ' + totalVol.toFixed(0) + '%)';
    epaResEl.style.color = color;
  }

  [bVEl, aVEl, rVEl, fVEl].forEach(el => el.addEventListener('input', update));
  update();
})();

reinforced-concrete-beam-ultimate-moment.js:
(() => {
  'use strict';
  const bEl = document.getElementById('rc-b'), dEl = document.getElementById('rc-d'), asEl = document.getElementById('rc-as');
  const fcEl = document.getElementById('rc-fc'), fyEl = document.getElementById('rc-fy');
  const phiMnResEl = document.getElementById('rc-res-phi-mn'), whResEl = document.getElementById('rc-res-whitney');

  function update() {
    const b = parseFloat(bEl.value), d = parseFloat(dEl.value), As = parseFloat(asEl.value);
    const fc = parseFloat(fcEl.value), fy = parseFloat(fyEl.value);

    if (isNaN(b) || isNaN(d) || isNaN(As) || isNaN(fc) || isNaN(fy) || b <= 0 || d <= 0 || As <= 0 || fc <= 0 || fy <= 0) return;

    // Whitney stress block depth a = ( As * fy ) / ( 0.85 * fc * b )  [mm]
    const a = (As * fy) / (0.85 * fc * b);

    // Nominal moment capacity: Mn = As * fy * ( d - a/2 )  [N * mm]
    const Mn_Nmm = As * fy * (d - (a / 2.0));
    const Mn_kNm = Mn_Nmm / 1e6;

    // Design moment capacity (tension-controlled phi = 0.90):
    const phi = 0.90;
    const phi_Mn_kNm = phi * Mn_kNm;

    // Reinforcement ratio rho = As / (b * d)
    const rho = (As / (b * d)) * 100.0;

    phiMnResEl.textContent = 'Design φ·M_n = ' + phi_Mn_kNm.toFixed(2) + ' kN·m';
    whResEl.textContent = 'Nominal M_n = ' + Mn_kNm.toFixed(2) + ' kN·m | a = ' + a.toFixed(2) + ' mm (Lever arm: ' + (d - a/2).toFixed(1) + ' mm | Rebar Ratio ρ = ' + rho.toFixed(2) + '%)';
  }

  [bEl, dEl, asEl, fcEl, fyEl].forEach(el => el.addEventListener('input', update));
  update();
})();

relative-vorticity-rossby-wave-speed-cal.js:
(() => {
  'use strict';
  const uEl = document.getElementById('ros-u'), wEl = document.getElementById('ros-wlen'), latEl = document.getElementById('ros-lat');
  const cResEl = document.getElementById('ros-res-c'), stResEl = document.getElementById('ros-res-stat');

  const omega = 7.2921159e-5;
  const R_earth = 6.371e6; // meters

  function update() {
    const u = parseFloat(uEl.value), L_km = parseFloat(wEl.value), lat = parseFloat(latEl.value);
    if (isNaN(u) || isNaN(L_km) || isNaN(lat) || L_km <= 0 || Math.abs(lat) > 90) return;

    const latRad = (lat * Math.PI) / 180;
    // Beta = 2 * omega * cos(lat) / R_earth  [m^-1 s^-1]
    const beta = (2 * omega * Math.cos(latRad)) / R_earth;

    const L_m = L_km * 1000;
    // Wavenumber k = 2 * pi / L
    const k = (2 * Math.PI) / L_m;

    // Phase speed c = u - (beta / k^2)  [m / s]
    const c = u - (beta / Math.pow(k, 2));
    const cKmh = c * 3.6;

    // Stationary wavelength L_s where c = 0 => k_s^2 = beta / u => L_s = 2*pi*sqrt(u / beta)
    const Ls_m = 2 * Math.PI * Math.sqrt(u / beta);
    const Ls_km = Ls_m / 1000;

    let dir = c >= 0 ? 'Eastward Progressive' : 'Westward Retrograde';
    cResEl.textContent = 'c = ' + (c >= 0 ? '+' : '') + c.toFixed(1) + ' m / s (' + cKmh.toFixed(1) + ' km/h ' + dir + ')';
    stResEl.textContent = 'Stationary Wavelength L_s = ' + Math.round(Ls_km).toLocaleString() + ' km (Waves longer than L_s retrogress westward)';
  }

  [uEl, wEl, latEl].forEach(el => el.addEventListener('input', update));
  update();
})();

relativistic-beaming-doppler-boosting-bl.js:
(() => {
  'use strict';
  const bEl = document.getElementById('rb-beta'), thEl = document.getElementById('rb-theta');
  const dlResEl = document.getElementById('rb-res-delta'), btResEl = document.getElementById('rb-res-boost');

  function update() {
    const beta = parseFloat(bEl.value), theta_deg = parseFloat(thEl.value);
    if (isNaN(beta) || isNaN(theta_deg) || beta <= 0 || beta >= 1 || theta_deg < 0 || theta_deg > 90) return;

    const theta_rad = (theta_deg * Math.PI) / 180.0;

    // Lorentz factor gamma = 1 / sqrt(1 - beta^2)
    const gamma = 1.0 / Math.sqrt(1.0 - Math.pow(beta, 2));

    // Doppler factor delta = 1 / [ gamma * ( 1 - beta * cos(theta) ) ]
    const delta = 1.0 / (gamma * (1.0 - beta * Math.cos(theta_rad)));

    // Apparent transverse velocity: beta_app = (beta * sin(theta)) / ( 1 - beta * cos(theta) )
    const beta_app = (beta * Math.sin(theta_rad)) / (1.0 - beta * Math.cos(theta_rad));

    // Flux boosting factor approx: S_obs / S0 = delta^(3 + alpha) where spectral index alpha ~ 0.7 => delta^3.7
    const flux_boost = Math.pow(delta, 3.7);

    dlResEl.textContent = 'Doppler Factor δ = ' + delta.toFixed(2) + ' (Lorentz γ = ' + gamma.toFixed(2) + ')';
    btResEl.textContent = 'Apparent Speed = ' + beta_app.toFixed(2) + ' c (' + (beta_app > 1.0 ? 'SUPERLUMINAL ILLUSION' : 'Subluminal') + ') | Flux Boost = ' + (flux_boost >= 1000 ? flux_boost.toExponential(2) : flux_boost.toFixed(1)) + '×';
  }

  bEl.addEventListener('input', update);
  thEl.addEventListener('input', update);
  update();
})();

relativistic-kinetic-energy-calculator.js:
(() => {
  'use strict';
  const mEl = document.getElementById('rke-mass'), bEl = document.getElementById('rke-beta');
  const keResEl = document.getElementById('rke-res-ke'), gResEl = document.getElementById('rke-res-gamma'), tResEl = document.getElementById('rke-res-tot');

  const cSpeed = 299792458; // m / s
  const eVToJ = 1.602176634e-19;

  function update() {
    const mKg = parseFloat(mEl.value), beta = parseFloat(bEl.value);
    if (isNaN(mKg) || isNaN(beta) || mKg <= 0 || beta < 0 || beta >= 1.0) return;

    // Lorentz factor gamma = 1 / sqrt(1 - beta^2)
    const gamma = 1 / Math.sqrt(1 - Math.pow(beta, 2));
    // Rest Energy E0 = m * c^2 (Joules)
    const E0_J = mKg * Math.pow(cSpeed, 2);
    // Kinetic energy K = (gamma - 1) * E0
    const K_J = (gamma - 1) * E0_J;
    // Total energy E = gamma * E0
    const E_tot_J = gamma * E0_J;

    const K_eV = K_J / eVToJ;
    const E_tot_eV = E_tot_J / eVToJ;

    if (mKg < 1e-20) {
      // Subatomic formatting in MeV/GeV
      keResEl.textContent = K_eV >= 1e9 ? (K_eV / 1e9).toFixed(3) + ' GeV' : (K_eV / 1e6).toFixed(3) + ' MeV';
      tResEl.textContent = E_tot_eV >= 1e9 ? (E_tot_eV / 1e9).toFixed(3) + ' GeV' : (E_tot_eV / 1e6).toFixed(3) + ' MeV';
    } else {
      // Macroscopic formatting in Joules
      keResEl.textContent = (K_J / 1e15).toFixed(2) + ' Petajoules (' + K_J.toExponential(2) + ' J)';
      tResEl.textContent = (E_tot_J / 1e15).toFixed(2) + ' Petajoules';
    }

    gResEl.textContent = 'γ = ' + gamma.toFixed(3);
  }

  mEl.addEventListener('change', update);
  bEl.addEventListener('input', update);
  update();
})();

relativistic-rocket-tsiolkovsky-proper-t.js:
(() => {
  'use strict';
  const mrEl = document.getElementById('rel-mr'), veEl = document.getElementById('rel-ve'), dEl = document.getElementById('rel-dist');
  const vResEl = document.getElementById('rel-res-v'), tmResEl = document.getElementById('rel-res-time');

  function update() {
    const mass_ratio = parseFloat(mrEl.value), ve_c = parseFloat(veEl.value), dist_ly = parseFloat(dEl.value);
    if (isNaN(mass_ratio) || isNaN(ve_c) || isNaN(dist_ly) || mass_ratio <= 1.0 || ve_c <= 0 || ve_c > 1.0 || dist_ly <= 0) return;

    // Relativistic Tsiolkovsky equation:
    // v / c = tanh( (v_e / c) * ln( m0 / mf ) )
    const rapidity = ve_c * Math.log(mass_ratio);
    const beta = Math.tanh(rapidity); // v / c

    // Lorentz dilation factor gamma = 1 / sqrt(1 - beta^2) = cosh(rapidity)
    const gamma = 1.0 / Math.sqrt(1.0 - Math.pow(beta, 2));

    // Earth coordinate time to travel distance d at speed v: t_earth = d / v  [years]
    const t_earth_years = dist_ly / beta;

    // Astronaut shipboard proper time tau = t_earth / gamma  [years]
    const tau_ship_years = t_earth_years / gamma;

    vResEl.textContent = 'Final v = ' + beta.toFixed(3) + ' c (Lorentz γ = ' + gamma.toFixed(2) + ')';
    tmResEl.textContent = 'Ship Proper Time τ = ' + tau_ship_years.toFixed(2) + ' yrs | Earth Time t = ' + t_earth_years.toFixed(2) + ' yrs (' + dist_ly + ' ly Voyage @ v_e = ' + ve_c + ' c)';
  }

  [mrEl, veEl, dEl].forEach(el => el.addEventListener('input', update));
  update();
})();

rental-property-cap-rate-calculator.js:
(() => {
  'use strict';
  const pEl = document.getElementById('cap-price'), rEl = document.getElementById('cap-rent'), eEl = document.getElementById('cap-exp');
  const rateEl = document.getElementById('cap-res-rate'), noiEl = document.getElementById('cap-res-noi'), grossEl = document.getElementById('cap-res-gross');

  function update() {
    const price = parseFloat(pEl.value), mRent = parseFloat(rEl.value), annualExp = parseFloat(eEl.value);
    if (isNaN(price) || isNaN(mRent) || isNaN(annualExp) || price <= 0 || mRent <= 0 || annualExp < 0) return;

    const annualGross = mRent * 12;
    // NOI = Annual Gross Rent - Annual Operating Expenses
    const noi = annualGross - annualExp;
    // Cap Rate = (NOI / Price) * 100
    const capRate = (noi / price) * 100;
    const grossYield = (annualGross / price) * 100;

    rateEl.textContent = capRate.toFixed(2) + '%';
    rateEl.style.color = capRate >= 6 ? '#22543d' : (capRate >= 4 ? '#2563eb' : '#d97706');
    noiEl.textContent = '$' + Math.round(noi).toLocaleString() + ' / yr';
    grossEl.textContent = grossYield.toFixed(2) + '%';
  }

  [pEl, rEl, eEl].forEach(el => el.addEventListener('input', update));
  update();
})();

reservoir-drive-mechanism-recovery-facto.js:
(() => {
