(() => {
  'use strict';
  const vmEl = document.getElementById('lg-vmass'), vlEl = document.getElementById('lg-vlen');
  const ilEl = document.getElementById('lg-ilen'), rtEl = document.getElementById('lg-ratio');
  const imResEl = document.getElementById('lg-res-imass'), pmResEl = document.getElementById('lg-res-pmol');

  function update() {
    const vector_ng = parseFloat(vmEl.value), vector_bp = parseFloat(vlEl.value);
    const insert_bp = parseFloat(ilEl.value), ratio = parseFloat(rtEl.value);

    if (isNaN(vector_ng) || isNaN(vector_bp) || isNaN(insert_bp) || vector_ng <= 0 || vector_bp <= 0 || insert_bp <= 0) return;

    // Ligation formula: Insert Mass (ng) = Vector Mass (ng) * ( Insert Length / Vector Length ) * Molar Ratio
    const insert_ng = vector_ng * (insert_bp / vector_bp) * ratio;

    // Picomoles = ( Mass in ng * 1000 ) / ( Length in bp * 650 daltons/bp )
    const pmol_vector = (vector_ng * 1000.0) / (vector_bp * 650.0);
    const pmol_insert = (insert_ng * 1000.0) / (insert_bp * 650.0);

    imResEl.textContent = 'Required Insert Mass = ' + insert_ng.toFixed(1) + ' ng';
    pmResEl.textContent = 'Vector: ' + pmol_vector.toFixed(3) + ' pmol (' + vector_ng + ' ng) | Insert: ' + pmol_insert.toFixed(3) + ' pmol (' + insert_ng.toFixed(1) + ' ng @ ' + ratio + ':1 Ratio)';
  }

  [vmEl, vlEl, ilEl].forEach(el => el.addEventListener('input', update));
  rtEl.addEventListener('change', update);
  update();
})();

retaining-wall-active-earth-pressure-ran.js:
(() => {
  'use strict';
  const pEl = document.getElementById('rw-phi'), gEl = document.getElementById('rw-gamma'), hEl = document.getElementById('rw-h');
  const paResEl = document.getElementById('rw-res-pa'), kaResEl = document.getElementById('rw-res-ka'), aResEl = document.getElementById('rw-res-arm');

  function update() {
    const phiDeg = parseFloat(pEl.value), gamma = parseFloat(gEl.value), H = parseFloat(hEl.value);
    if (isNaN(phiDeg) || isNaN(gamma) || isNaN(H) || phiDeg <= 0 || phiDeg >= 90 || gamma <= 0 || H <= 0) return;

    const phiRad = (phiDeg * Math.PI) / 180;
    const sinPhi = Math.sin(phiRad);

    // K_a = (1 - sin(phi)) / (1 + sin(phi))
    const Ka = (1 - sinPhi) / (1 + sinPhi);

    // Total resultant active thrust P_a = 0.5 * Ka * gamma * H^2 (kN per meter of wall length)
    const Pa = 0.5 * Ka * gamma * Math.pow(H, 2);
    // Line of action is at H / 3 from base
    const arm = H / 3;

    paResEl.textContent = Pa.toFixed(2) + ' kN / m of wall';
    kaResEl.textContent = 'K_a = ' + Ka.toFixed(3);
    aResEl.textContent = arm.toFixed(2) + ' m above base (H / 3)';
  }

  [pEl, gEl, hEl].forEach(el => el.addEventListener('input', update));
  update();
})();

retaining-wall-overturning-sliding-facto.js:
(() => {
  'use strict';
  const mrEl = document.getElementById('rw-mr'), moEl = document.getElementById('rw-mo');
  const rvEl = document.getElementById('rw-rv'), phEl = document.getElementById('rw-ph'), muEl = document.getElementById('rw-mu');
  const fsoResEl = document.getElementById('rw-res-fso'), fssResEl = document.getElementById('rw-res-fss');

  function update() {
    const MR = parseFloat(mrEl.value), MO = parseFloat(moEl.value);
    const Rv = parseFloat(rvEl.value), Ph = parseFloat(phEl.value), mu = parseFloat(muEl.value);

    if (isNaN(MR) || isNaN(MO) || isNaN(Rv) || isNaN(Ph) || isNaN(mu) || MO <= 0 || Ph <= 0 || Rv <= 0 || mu <= 0) return;

    // FS against overturning = sum(M_R) / sum(M_O)
    const FS_ot = MR / MO;

    // Sliding resistance force Fr = mu * Rv  [kN / m]
    const Fr = mu * Rv;
    // FS against sliding = Fr / Ph
    const FS_sl = Fr / Ph;

    let otColor = FS_ot >= 2.0 ? '#22543d' : (FS_ot >= 1.5 ? '#d97706' : '#c53030');
    let slColor = FS_sl >= 1.5 ? '#22543d' : (FS_sl >= 1.2 ? '#d97706' : '#c53030');

    fsoResEl.textContent = 'FS_overturn = ' + FS_ot.toFixed(2) + ' (' + (FS_ot >= 2.0 ? 'SAFE ≥ 2.0 Code Compliant' : 'FAIL: Below 2.0 Minimum!') + ')';
    fsoResEl.style.color = otColor;

    fssResEl.textContent = 'FS_sliding = ' + FS_sl.toFixed(2) + ' (' + (FS_sl >= 1.5 ? 'SAFE ≥ 1.5' : 'FAIL: Base Key or Wider Footing Required!') + ' | Resisting Force F_r = ' + Fr.toFixed(1) + ' kN/m)';
    fssResEl.style.color = slColor;
  }

  [mrEl, moEl, rvEl, phEl, muEl].forEach(el => el.addEventListener('input', update));
  update();
})();

retaining-wall-rankine-active-passive-ea.js:
(() => {
  'use strict';
  const phiEl = document.getElementById('rk-phi'), gEl = document.getElementById('rk-gamma'), hEl = document.getElementById('rk-h');
  const paResEl = document.getElementById('rk-res-pa'), cfResEl = document.getElementById('rk-res-coeff');

  function update() {
    const phi_deg = parseFloat(phiEl.value), gamma = parseFloat(gEl.value), H = parseFloat(hEl.value);
    if (isNaN(phi_deg) || isNaN(gamma) || isNaN(H) || phi_deg <= 0 || phi_deg >= 90 || gamma <= 0 || H <= 0) return;

    const phi_rad = (phi_deg * Math.PI) / 180.0;
    const sin_phi = Math.sin(phi_rad);

    // Rankine active coefficient: K_a = ( 1 - sin(phi) ) / ( 1 + sin(phi) )
    const K_a = (1.0 - sin_phi) / (1.0 + sin_phi);

    // Rankine passive coefficient: K_p = ( 1 + sin(phi) ) / ( 1 - sin(phi) ) = 1 / K_a
    const K_p = (1.0 + sin_phi) / (1.0 - sin_phi);

    // Total active thrust force: P_a = 0.5 * K_a * gamma * H^2  [kN / m]
    const P_a = 0.5 * K_a * gamma * Math.pow(H, 2);

    // Overturning moment about the toe: M_ot = P_a * (H / 3)  [kN * m / m]
    const M_ot = P_a * (H / 3.0);

    paResEl.textContent = 'Active Thrust P_a = ' + P_a.toFixed(2) + ' kN / m';
    cfResEl.textContent = 'K_a = ' + K_a.toFixed(3) + ' | K_p = ' + K_p.toFixed(3) + ' | Overturning M_ot = ' + M_ot.toFixed(2) + ' kN·m/m (Thrust acting at ' + (H/3.0).toFixed(2) + ' m above base)';
  }

  [phiEl, gEl, hEl].forEach(el => el.addEventListener('input', update));
  update();
})();

