reverberation-time-rt60-sabine-calculato.js:
(() => {
  'use strict';
  const lEl = document.getElementById('rt-len'), wEl = document.getElementById('rt-wid'), hEl = document.getElementById('rt-ht'), aEl = document.getElementById('rt-alpha');
  const tEl = document.getElementById('rt-res-time'), vEl = document.getElementById('rt-res-vol');

  function update() {
    const L = parseFloat(lEl.value), W = parseFloat(wEl.value), H = parseFloat(hEl.value), alpha = parseFloat(aEl.value);
    if (isNaN(L) || isNaN(W) || isNaN(H) || isNaN(alpha) || L <= 0 || W <= 0 || H <= 0 || alpha <= 0) return;

    // Room volume V = L * W * H
    const V = L * W * H;
    // Total boundary surface area S = 2*(LW + LH + WH)
    const S = 2 * (L * W + L * H + W * H);
    // Total absorption A = S * alpha (metric Sabins)
    const A = S * alpha;
    // RT60 = 0.161 * V / A
    const rt60 = (0.161 * V) / A;

    tEl.textContent = rt60.toFixed(2) + ' seconds';
    vEl.textContent = V.toFixed(1) + ' m³ (' + S.toFixed(1) + ' m² surfaces)';
  }

  [lEl, wEl, hEl, aEl].forEach(el => el.addEventListener('input', update));
  update();
})();

reverberation-time-sabine-eyring-calcula.js:
(() => {
  'use strict';
  const vEl = document.getElementById('rt-vol'), sEl = document.getElementById('rt-surf'), aEl = document.getElementById('rt-alpha');
  const rResEl = document.getElementById('rt-res-rt60'), tResEl = document.getElementById('rt-res-type');

  function update() {
    const V = parseFloat(vEl.value), S = parseFloat(sEl.value), alpha = parseFloat(aEl.value);
    if (isNaN(V) || isNaN(S) || isNaN(alpha) || V <= 0 || S <= 0 || alpha <= 0 || alpha >= 1.0) return;

    // Total absorption in Sabins: A = S * alpha
    const A = S * alpha;

    // Sabine RT60 = 0.161 * V / A  [seconds]
    const rtSabine = (0.161 * V) / A;

    // Eyring RT60 = 0.161 * V / ( -S * ln(1 - alpha) )
    const rtEyring = (0.161 * V) / (-S * Math.log(1 - alpha));

    let acousticCategory = '';
    if (rtSabine < 0.4) acousticCategory = 'Dry Recording Booth / Broadcast Studio (<0.4s)';
    else if (rtSabine <= 0.7) acousticCategory = 'Optimal Classroom & Audio Control Room (0.4 - 0.7s)';
    else if (rtSabine <= 1.2) acousticCategory = 'Chamber Music Hall & Multipurpose Auditorium (0.8 - 1.2s)';
    else if (rtSabine <= 2.2) acousticCategory = 'Symphony Concert Hall (1.5 - 2.2s Warm Acoustic Resonance)';
    else acousticCategory = 'Cathedral / Church Echo Chamber (>2.2s High Reverberance)';

    rResEl.textContent = 'RT₆₀ = ' + rtSabine.toFixed(3) + ' s (Sabine)';
    tResEl.textContent = acousticCategory + ' | Eyring: ' + rtEyring.toFixed(3) + ' s (Total Absorption: ' + Math.round(A) + ' metric Sabins)';
  }

  [vEl, sEl, aEl].forEach(el => el.addEventListener('input', update));
  update();
})();

reverse-osmosis-membrane-salt-rejection-.js:
(() => {
  'use strict';
  const pEl = document.getElementById('ro-p'), cfEl = document.getElementById('ro-cf');
  const cpEl = document.getElementById('ro-cp'), aEl = document.getElementById('ro-a');
  const flResEl = document.getElementById('ro-res-flux'), rjResEl = document.getElementById('ro-res-rej');

  function update() {
    const P_bar = parseFloat(pEl.value), C_f = parseFloat(cfEl.value);
    const C_p = parseFloat(cpEl.value), A_perm = parseFloat(aEl.value);

    if (isNaN(P_bar) || isNaN(C_f) || isNaN(C_p) || isNaN(A_perm) || P_bar <= 0 || C_f <= 0 || C_p < 0 || A_perm <= 0) return;

    // Osmotic pressure approx for seawater: pi approx 0.8 bar per 1000 mg/L TDS (van 't Hoff rule)
    const pi_bar = (C_f / 1000.0) * 0.80;

    // Net Driving Pressure: NDP = Delta_P - Delta_pi
    const NDP = Math.max(0.0, P_bar - pi_bar);

    // Permeate flux: J_w = A * NDP  [L / (m^2 * hr) = LMH]
    const J_w = A_perm * NDP;

    // Salt rejection efficiency: R = ( 1 - C_p / C_f ) * 100%
    const R_pct = (1.0 - (C_p / C_f)) * 100.0;

    flResEl.textContent = 'Water Flux J_w = ' + J_w.toFixed(1) + ' LMH (L/m²·hr)';
    rjResEl.textContent = 'Salt Rejection R = ' + R_pct.toFixed(2) + '% | Osmotic π = ' + pi_bar.toFixed(1) + ' bar (NDP = ' + NDP.toFixed(1) + ' bar @ P=' + P_bar + ' bar)';
  }

  [pEl, cfEl, cpEl, aEl].forEach(el => el.addEventListener('input', update));
  update();
})();

